INSERT INTO settlement_aliases (settlement_id, alias)
SELECT s.id, aliases.alias
FROM settlements s
JOIN reference_sources source ON source.id = s.source_id
CROSS JOIN (VALUES ('Gravesend')) AS aliases(alias)
WHERE source.source_key = 'ons_bua_2022_gb' AND s.external_code = 'E63005058'
ON CONFLICT (settlement_id, alias) DO NOTHING;

WITH source AS (
  SELECT id FROM reference_sources WHERE source_key = 'ons_bua_2022_gb'
), settlement AS (
  INSERT INTO settlements (source_id, external_code, name, nation, is_active)
  SELECT source.id, 'E63005204', 'Gillingham (Medway)', 'England', TRUE FROM source
  ON CONFLICT (source_id, external_code) DO UPDATE
    SET name = EXCLUDED.name, nation = EXCLUDED.nation, is_active = TRUE
  RETURNING id, source_id
), ensured AS (
  SELECT id, source_id FROM settlement
  UNION ALL
  SELECT s.id, s.source_id FROM settlements s
  JOIN source ON source.id = s.source_id
  WHERE s.external_code = 'E63005204'
)
